// The user's Claude API key. By default it lives only in memory for this tab.
// If the user opts in to "remember on this device", it is encrypted with a
// non-exportable AES-GCM key generated by the browser and both are kept in
// IndexedDB. This protects the key at rest from casual reading of storage
// files; it cannot protect against code running inside this page, which is
// why the app ships a strict Content Security Policy and renders no HTML
// from AI output.

import { getOne, put, remove } from "./db";

interface VaultRecord {
  id: string;
  cryptoKey: CryptoKey;
  iv: Uint8Array;
  data: ArrayBuffer;
  hint: string;
  savedAt: number;
}

const ID = "anthropic-api-key";
let current: string | null = null;
let remembered = false;
const listeners = new Set<() => void>();

export function subscribeKey(fn: () => void) {
  listeners.add(fn);
  return () => listeners.delete(fn);
}
const emit = () => listeners.forEach((l) => l());

export function getApiKey(): string | null {
  return current;
}
export function isRemembered() {
  return remembered;
}
export function keyHint(): string {
  return current ? `sk-ant-…${current.slice(-4)}` : "";
}

/** Checks the shape of a key before it is ever sent anywhere. */
export function validateKeyFormat(key: string): string | null {
  const k = key.trim();
  if (!k) return "Paste your API key.";
  if (!k.startsWith("sk-ant-")) return "Claude API keys start with sk-ant-. Create one in the Claude Console under API keys.";
  if (k.length < 24 || k.length > 400) return "That key is the wrong length. Copy the whole key from the Claude Console.";
  if (!/^[A-Za-z0-9_-]+$/.test(k)) return "The key contains characters an API key never has. Check for spaces or line breaks.";
  return null;
}

export async function setApiKey(key: string, remember: boolean) {
  const k = key.trim();
  const err = validateKeyFormat(k);
  if (err) throw new Error(err);
  current = k;
  remembered = false;
  await remove("vault", ID).catch(() => undefined);
  if (remember) {
    const cryptoKey = await crypto.subtle.generateKey({ name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]);
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const data = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, cryptoKey, new TextEncoder().encode(k));
    const rec: VaultRecord = { id: ID, cryptoKey, iv, data, hint: k.slice(-4), savedAt: Date.now() };
    await put("vault", rec);
    remembered = true;
  }
  emit();
}

export async function forgetApiKey() {
  current = null;
  remembered = false;
  await remove("vault", ID).catch(() => undefined);
  emit();
}

/** Load a remembered key at startup. Silently ignores a missing or unreadable record. */
export async function loadRememberedKey(): Promise<boolean> {
  try {
    const rec = await getOne<VaultRecord>("vault", ID);
    if (!rec) return false;
    const plain = await crypto.subtle.decrypt({ name: "AES-GCM", iv: new Uint8Array(rec.iv) }, rec.cryptoKey, rec.data);
    const k = new TextDecoder().decode(plain);
    if (validateKeyFormat(k)) return false;
    current = k;
    remembered = true;
    emit();
    return true;
  } catch {
    return false;
  }
}
